{
	var i: nat := 1;
	max := a[0];
	while i < a.Length
	invariant 0 <= i <= a.Length
	invariant forall j :: 0 <= j < i ==> a[j] <= max
	invariant exists j :: 0 <= j < i && a[j] == max
